"""
Wait policies for rollup partition mappers.

A :class:`WaitPolicy` decides, given the set of upstream partition keys that
have actually arrived (*matched*) and the full set the window declares
(*expected*), whether a rollup downstream Dag run should fire. It also decides
whether the policy is *permanently unreachable* for a given window — a state
the scheduler surfaces as a warning instead of holding the run forever.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass


@dataclass
class PartitionSatisfaction:
    """
    Result of evaluating a :class:`WaitPolicy` against a set of keys.

    Enforces the cross-field invariant at construction time: ``unreachable`` and
    ``unreachable_reason`` must be provided together (a reason is required when
    unreachable, and forbidden otherwise).
    """

    satisfied: bool
    unreachable: bool = False
    unreachable_reason: str | None = None

    def __post_init__(self) -> None:
        if self.unreachable and self.unreachable_reason is None:
            raise ValueError("unreachable_reason must be set when unreachable is True")
        if not self.unreachable and self.unreachable_reason is not None:
            raise ValueError("unreachable_reason must be None when unreachable is False")


class WaitPolicy(ABC):
    """
    Abstract base class for rollup wait policies.

    Subclasses implement :meth:`is_satisfied` (does the arrived count clear the
    bar?) and :meth:`is_unreachable` (can the bar ever be cleared given the
    window size?). The default :meth:`is_satisfied_by_keys` converts the two key
    sets to counts and delegates to those hooks.
    """

    @abstractmethod
    def is_satisfied(self, matched: int, expected: int) -> bool:
        """Return whether *matched* arrived keys satisfy the policy for an *expected*-sized window."""

    @abstractmethod
    def is_unreachable(self, expected: int) -> bool:
        """Return whether the policy can never be satisfied for an *expected*-sized window."""

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        """
        Evaluate the policy against the *matched* and *expected* key sets.

        Counts the keys that have actually arrived (the intersection of
        *matched* and *expected*) and delegates the decision to
        :meth:`is_satisfied`. When :meth:`is_unreachable` reports that the
        window can never satisfy the policy, returns an ``unreachable`` result
        carrying a human-readable reason instead.
        """
        expected_count = len(expected)
        if self.is_unreachable(expected_count):
            reason = (
                f"wait policy {self!r} can never be satisfied given the "
                f"window's cardinality {len(expected)}"
            )
            return PartitionSatisfaction(satisfied=False, unreachable=True, unreachable_reason=reason)
        matched_count = len(matched & expected)
        return PartitionSatisfaction(satisfied=self.is_satisfied(matched_count, expected_count))


class WaitForAll(WaitPolicy):
    """
    Fire only when every expected upstream partition key is present.

    Stateless: all instances are equal and hash equal. The
    :meth:`is_satisfied_by_keys` override short-circuits to a superset check.
    """

    def __repr__(self) -> str:
        return "WaitForAll()"

    def __eq__(self, other: object) -> bool:
        return type(other).__name__ == "WaitForAll"

    def __hash__(self) -> int:
        return hash("WaitForAll")

    def is_satisfied(self, matched: int, expected: int) -> bool:
        return matched == expected

    def is_unreachable(self, expected: int) -> bool:
        return False

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        return PartitionSatisfaction(satisfied=matched >= expected)

    def serialize(self) -> dict:
        return {}

    @classmethod
    def deserialize(cls, data: dict) -> WaitForAll:
        return cls()


class MinimumCount(WaitPolicy):
    """
    Fire once at least *n* upstream partition keys have arrived.

    Positive ``n`` is an absolute threshold: fire when ``matched >= n``.
    Negative ``n`` is relative to the window size: fire when
    ``matched >= max(0, expected + n)`` (e.g. ``n=-3`` fires once all but three
    keys have arrived). ``n=0`` is degenerate and rejected.
    """

    def __init__(self, n: int) -> None:
        if n == 0:
            raise ValueError("MinimumCount(0) is degenerate; use a positive or negative threshold")
        self.n = n

    def __repr__(self) -> str:
        return f"MinimumCount(n={self.n})"

    def __eq__(self, other: object) -> bool:
        return type(other).__name__ == "MinimumCount" and other.n == self.n  # type: ignore[attr-defined]

    def __hash__(self) -> int:
        return hash(("MinimumCount", self.n))

    def is_satisfied(self, matched: int, expected: int) -> bool:
        if self.n > 0:
            return matched >= self.n
        return matched >= max(0, expected + self.n)

    def is_unreachable(self, expected: int) -> bool:
        return self.n > 0 and self.n > expected

    def serialize(self) -> dict:
        return {"n": self.n}

    @classmethod
    def deserialize(cls, data: dict) -> MinimumCount:
        return cls(data["n"])
