    """
    importable_string = _serializer.BUILTIN_WAIT_POLICIES.get(type(var))
    if importable_string is None:
        raise WaitPolicyNotSupported(qualname(type(var)))
    return {
        Encoding.TYPE: importable_string,
        Encoding.VAR: _serializer.serialize_wait_policy(var),
